def findMaxProfit(arr):

    n = len(arr)

    # Initialize profit list with 0
    profit = [0]*n

    # Calculate profit for each transaction
    for i in range(1, n):
        profit[i] = max(profit[i-1], arr[i] - min(arr[:i]))

    # Return maximum profit
    return max(profit[n-1], profit[n-2])

